"use client";
import { useEffect, useState } from "react";
import { ReplayView } from "@/components/replay-view";

/**
 * Offline demo replay: plays /replays/demo.json (generated by `npm run sim -- --out apps/web/public/replays/demo.json`).
 * Works without the API — useful for the visual designer. Drop any echo-replay/1 file onto the page to view it.
 */
export default function DemoReplay() {
  const [replay, setReplay] = useState<any>(null);
  const [err, setErr] = useState("");
  useEffect(() => {
    fetch("/replays/demo.json").then((r) => (r.ok ? r.json() : Promise.reject(new Error("没有找到 /replays/demo.json")))).then(setReplay).catch((e) => setErr(e.message));
  }, []);
  const onDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    const f = e.dataTransfer.files[0];
    if (!f) return;
    try {
      const j = JSON.parse(await f.text());
      if (j.format !== "echo-replay/1") throw new Error("不是 echo-replay/1 文件");
      setReplay(j);
      setErr("");
    } catch (x: any) {
      setErr(x.message);
    }
  };
  return (
    <div onDragOver={(e) => e.preventDefault()} onDrop={onDrop}>
      {err && <div className="wrap block"><p className="grey">{err}。把回放 JSON 拖到这里即可播放。</p></div>}
      {replay && <ReplayView key={`${replay.id}:${replay.seed}:${replay.events.length}`} replay={replay} />}
    </div>
  );
}
